package com.xianshuyuan.scm.customer.service;
import com.xianshuyuan.scm.common.exception.BusinessException;import com.xianshuyuan.scm.customer.converter.CustomerConverter;import com.xianshuyuan.scm.customer.dto.AgreementPriceSaveRequest;import com.xianshuyuan.scm.customer.entity.CustomerAgreementPriceEntity;import com.xianshuyuan.scm.customer.mapper.CustomerAgreementPriceMapper;import com.xianshuyuan.scm.customer.vo.AgreementPriceResponse;import com.xianshuyuan.scm.product.mapper.ProductSkuMapper;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.util.*;
@Service public class AgreementPriceService {private final CustomerAgreementPriceMapper prices;private final CustomerService customers;private final ProductSkuMapper skus;private final AgreementPriceValidator validator;public AgreementPriceService(CustomerAgreementPriceMapper p,CustomerService c,ProductSkuMapper s,AgreementPriceValidator v){prices=p;customers=c;skus=s;validator=v;}public List<AgreementPriceResponse> list(){return prices.selectActive().stream().map(this::response).toList();}@Transactional public long create(AgreementPriceSaveRequest r){validate(r,null);var e=CustomerConverter.toPrice(r);e.setVersion(0);e.setDeleted(false);e.setCreatedBy("SYSTEM");prices.insert(e);return e.getId();}@Transactional public void update(long id,AgreementPriceSaveRequest r){require(id);if(r.version()==null)throw new BusinessException(CustomerErrorCodes.VERSION_CONFLICT);validate(r,id);var e=CustomerConverter.toPrice(r);e.setId(id);if(prices.updateById(e)!=1)throw new BusinessException(CustomerErrorCodes.VERSION_CONFLICT);}@Transactional public void delete(long id,int version){var e=require(id);if(!Objects.equals(e.getVersion(),version))throw new BusinessException(CustomerErrorCodes.VERSION_CONFLICT);prices.deleteById(id);}private void validate(AgreementPriceSaveRequest r,Long id){validator.validate(r);customers.require(r.customerId());if(skus.selectById(r.skuId())==null)throw new BusinessException(CustomerErrorCodes.SKU_NOT_VISIBLE);if(prices.countOverlapping(id,r.customerId(),r.skuId(),r.effectiveFrom(),r.effectiveTo())>0)throw new BusinessException(CustomerErrorCodes.AGREEMENT_PRICE_OVERLAP);}private CustomerAgreementPriceEntity require(long id){var e=prices.selectById(id);if(e==null)throw new BusinessException(CustomerErrorCodes.AGREEMENT_PRICE_NOT_FOUND);return e;}private AgreementPriceResponse response(CustomerAgreementPriceEntity e){return new AgreementPriceResponse(e.getId(),e.getVersion(),e.getCustomerId(),e.getSkuId(),e.getUnitPrice().setScale(4).toPlainString(),e.getEffectiveFrom(),e.getEffectiveTo());}}
